Vrtc vrtc_f_create( Exec_Func func  )
{    
	Vrtc_F vrtc_f = (Vrtc_F)vrtc_build( (Vrtc_Func)vrtc_f_irq_service , sizeof( struct s_Vrtc_F ) );
	
	if( vrtc_f )
	{
		vrtc_f->irq = FALSE ;

		vrtc_f->exec_func = func ; 
	
		irq_user_reg_func_arg( (Reg_Func)vrtc_f_user_service , (Reg_Own_Arg)vrtc_f );  
	};
	
	return (Vrtc)vrtc_f ; 	 
}

